import { render } from '@testing-library/react'
import type { ComponentType, SVGProps } from 'react'
import { describe, expect, it } from 'vitest'

import * as icons from '@/components/icons'
import * as logos from '@/components/logos'

type SvgComponent = ComponentType<SVGProps<SVGSVGElement> & { title?: string }>

/**
 * Contract of the components generated by scripts/iconConverter (`pnpm icons:generate`):
 * decorative by default, named only where they are used, coloured from CSS, and sized per
 * family (icons follow the font size, logos keep their viewBox ratio).
 */
const families = [
	{ name: 'icons', components: icons as Record<string, SvgComponent>, suffix: 'IconSvg' },
	{ name: 'logos', components: logos as Record<string, SvgComponent>, suffix: 'LogoSvg' },
]

const renderSvg = (Component: SvgComponent, props: { title?: string } = {}) => {
	const { container } = render(<Component {...props} />)
	const svg = container.querySelector('svg')
	if (!svg) throw new Error('Component did not render an <svg>')
	return svg
}

describe.each(families)('generated $name', ({ components, suffix }) => {
	const entries = Object.entries(components)

	it('exports at least one component', () => {
		expect(entries.length).toBeGreaterThan(0)
	})

	it.each(entries)('%s is named and decorative by default', (exportName, Component) => {
		expect(exportName).toMatch(new RegExp(`${suffix}$`))
		expect(Component.displayName).toBe(exportName)

		const svg = renderSvg(Component)
		expect(svg.getAttribute('aria-hidden')).toBe('true')
		expect(svg.hasAttribute('role')).toBe(false)
		expect(svg.hasAttribute('aria-label')).toBe(false)
		// Names come from the place of use (translatable), never from the source file.
		expect(svg.querySelector('title')).toBeNull()
	})

	it.each(entries)('%s becomes a named image when given a title', (_, Component) => {
		const svg = renderSvg(Component, { title: 'Accessible name' })
		expect(svg.getAttribute('role')).toBe('img')
		expect(svg.hasAttribute('aria-hidden')).toBe(false)
		expect(svg.querySelector('title')?.textContent).toBe('Accessible name')
	})

	it.each(entries)('%s paints only in currentColor', (_, Component) => {
		const svg = renderSvg(Component)
		for (const element of [svg, ...svg.querySelectorAll('*')]) {
			for (const attribute of ['fill', 'stroke']) {
				const value = element.getAttribute(attribute)
				if (value !== null)
					expect(['none', 'currentColor'], `${attribute}="${value}"`).toContain(value)
			}
		}
	})
})

describe('generated sizing', () => {
	it.each(Object.entries(icons))('%s is sized to the text (1em)', (_, Component) => {
		const svg = renderSvg(Component as SvgComponent)
		expect(svg.getAttribute('width')).toBe('1em')
		expect(svg.getAttribute('height')).toBe('1em')
	})

	it.each(Object.entries(logos))('%s keeps its ratio in the viewBox only', (_, Component) => {
		const svg = renderSvg(Component as SvgComponent)
		expect(svg.getAttribute('viewBox')).toMatch(/^[\d.-]+ [\d.-]+ [\d.]+ [\d.]+$/)
		expect(svg.hasAttribute('width')).toBe(false)
		expect(svg.hasAttribute('height')).toBe(false)
	})
})
